using JobOrbit.Application.Authorization;using JobOrbit.Application.DTOs.AdminUsers;using JobOrbit.Application.DTOs.Jobs;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace JobOrbit.API.Controllers;[ApiController,Route("api/admin/users"),Authorize(Roles=nameof(UserRole.Administrator))]public sealed class AdminUsersController(IAdminUserService service):ControllerBase{bool Id(out int id)=>int.TryParse(User.FindFirst("UserId")?.Value,out id);IActionResult Result(AdminUserMutationResult x,bool created=false)=>x.Outcome switch{AdminUserMutationOutcome.Success when created=>CreatedAtAction(nameof(Details),new{userId=x.User!.UserId},x.User),AdminUserMutationOutcome.Success=>Ok(x.User),AdminUserMutationOutcome.NotFound=>NotFound(),AdminUserMutationOutcome.DuplicateEmail=>Conflict(new ProblemDetails{Status=409,Title="Email is already registered"}),AdminUserMutationOutcome.DangerousRoleChange=>Conflict(new ProblemDetails{Status=409,Title="Role changes are not supported for existing users"}),AdminUserMutationOutcome.SelfStatusChange=>Conflict(new ProblemDetails{Status=409,Title="Administrators cannot deactivate their own account"}),AdminUserMutationOutcome.LastActiveAdmin=>Conflict(new ProblemDetails{Status=409,Title="The last active administrator cannot be deactivated"}),AdminUserMutationOutcome.InvalidOrganization=>BadRequest(new ProblemDetails{Status=400,Title="A valid organization is required"}),AdminUserMutationOutcome.InvalidDepartment=>BadRequest(new ProblemDetails{Status=400,Title="Department must belong to the selected organization"}),_=>BadRequest(new ProblemDetails{Status=400,Title="Invalid user role"})};[HttpGet,Authorize(Policy=PermissionConstants.AdminUsersView)]public async Task<IActionResult>List([FromQuery]AdminUserQuery q,CancellationToken t){if(!Id(out _))return Unauthorized();var x=await service.ListAsync(q,t);return x.Valid?Ok(x.Result):BadRequest(new ProblemDetails{Status=400,Title="Invalid role or status filter"});}[HttpGet("{userId:int}"),Authorize(Policy=PermissionConstants.AdminUsersView)]public async Task<IActionResult>Details(int userId,CancellationToken t)=>Id(out _)?await service.DetailsAsync(userId,t)is{}x?Ok(x):NotFound():Unauthorized();[HttpPost,Authorize(Policy=PermissionConstants.AdminUsersCreate)]public async Task<IActionResult>Create(CreateAdminUserRequest r,CancellationToken t)=>Id(out var id)?Result(await service.CreateAsync(id,r,t),true):Unauthorized();[HttpPut("{userId:int}"),Authorize(Policy=PermissionConstants.AdminUsersUpdate)]public async Task<IActionResult>Update(int userId,UpdateAdminUserRequest r,CancellationToken t)=>Id(out var id)?Result(await service.UpdateAsync(id,userId,r,t)):Unauthorized();[HttpPatch("{userId:int}/status"),Authorize(Policy=PermissionConstants.AdminUsersChangeStatus)]public async Task<IActionResult>Status(int userId,UpdateUserStatusRequest r,CancellationToken t)=>Id(out var id)?Result(await service.StatusAsync(id,userId,r,t)):Unauthorized();[HttpPost("{userId:int}/reset-password"),Authorize(Policy=PermissionConstants.AdminUsersResetPassword)]public async Task<IActionResult>Reset(int userId,AdminResetPasswordRequest r,CancellationToken t){if(!Id(out var id))return Unauthorized();return await service.ResetPasswordAsync(id,userId,r,t)==AdminUserMutationOutcome.Success?NoContent():NotFound();}}
